output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file pedestrian aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "An agent must not move into a single-file aisle while holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "opposing_shelf_aisles_are_cart_free",
    "text": "Aisles with shelves on both sides are pedestrian-only and carts are forbidden there.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "betweenOpposingShelves"
        ]
      }
    }
  },
  {
    "id": "no_cart_shelf_service_in_pedestrian_bay",
    "text": "Shelf interactions in narrow pedestrian shelf bays must be done without a cart.",
    "abstraction": {
      "state_properties": {
        "narrowShelfBay": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "narrowShelfBay"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_pedestrian_pick",
    "text": "After picking an item in a cart-free pedestrian aisle, the agent is obliged to retrieve a cart before finishing.",
    "abstraction": {
      "state_properties": {
        "pedestrianShelfBay": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "cartFreePedestrianShelfInteraction": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "pedestrianShelfBay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartFreePedestrianShelfInteraction",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_cartless_roaming_in_wide_corridors",
    "text": "Except at the entrance, cart bay, or a designated pedestrian-aisle mouth, agents should not walk through wide public corridors without a cart.",
    "abstraction": {
      "state_properties": {
        "widePublicCorridor": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "entranceOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "pedestrianAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "enterPedestrianAisleOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "pedestrianAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          "widePublicCorridor",
          {
            "not": "entranceOrCartBay"
          },
          {
            "not": "cartParkingMouth"
          },
          {
            "not": "enterPedestrianAisleOnFoot"
          }
        ]
      }
    }
  },
  {
    "id": "drop_cart_only_at_clear_aisle_mouth",
    "text": "Carts may only be set down at clear, wide aisle-mouth parking spots rather than beside merchandise shelves.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "clearWideMouth": {
          "and": [
            "cartParkingMouth",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartDrop",
          {
            "not": "clearWideMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_any_dropped_cart",
    "text": "Whenever an agent sets down a cart, they are obliged to pick it up again before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartPickup": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartDrop",
      "discharge": "cartPickup"
    }
  }
]
